    {
      "name": "邮递员老周",
      "function": "助力",
      "identity": "公寓片区邮递员，五十多岁",
      "description": "每天准时送信，对林晚收到奇怪邮戳的信感到疑惑，曾提醒她'这信不对劲'，但林晚没有在意"
    }
